package org.flxtr.android;
import org.junit.Test;
import static org.junit.Assert.*;
import org.json.*;
import java.util.*;
public class MediaPortTest {
 @Test public void animeCardsRejectOtherHosts() throws Exception {CatalogPage p=KissAnime.cards("<div class=listupd><article><a rel=12 title='Naruto' href='https://kissanime.com.cv/anime/naruto/'><img src='https://kissanime.com.cv/a.jpg'></a></article><article><a rel=14 title=Ads href='https://ads.example/anime/no'></a></article></div><div class=hpage><a class=r>Next</a></div>",2);assertEquals(1,p.items.size());assertEquals(12,p.items.get(0).id);assertEquals(3,p.pages);}
 @Test public void animeEpisodesSortFractionalNumbersAndPage(){StringBuilder html=new StringBuilder();for(int i=45;i>=1;i--)html.append("<a class=ep-item data-id=").append(100+i).append(" data-number=").append(i).append("></a>");html.append("<a class=ep-item data-id=999 data-number=1.5></a>");CatalogPage p=KissAnime.episodesHtml(html.toString(),10,1);assertEquals(20,p.items.size());assertEquals(101,p.items.get(0).id);assertEquals(999,p.items.get(1).id);assertEquals(10,p.items.get(1).season);assertEquals(3,p.pages);assertEquals(46,KissAnime.episodesHtml(html.toString(),10,0).items.size());}
 @Test public void encryptedAnimeFixtureMatchesNative() throws Exception {StreamProtocol.Stream s=KissAnime.mega(new JSONObject("{\"enc\":\"wdeBruh3qqn_i5wUNnyaPXE9vrvRetOe_eCsTM_CyaSDXrJbydon6awZjDd3oT-H\"}"),1000);assertEquals("https://media.example/video.m3u8",s.url);}
 @Test public void animeTokenExpiryAndIdempotence() throws Exception {String signed=KissAnime.token("https://media.example/a/0123456789abcdef0123456789abcdef/abcdef0123456789abcdef0123456789/master.m3u8",1000);String payload=signed.split("token=")[1].split("\\.")[0];assertEquals("1090|0123456789abcdef0123456789abcdef/abcdef0123456789abcdef0123456789",new String(Base64.getUrlDecoder().decode(payload),java.nio.charset.StandardCharsets.UTF_8));assertEquals(signed,KissAnime.token(signed,2000));}
 @Test public void animeDirectRejectsWebAndFileUrls(){assertEquals("",KissAnime.direct("<source src='file:///private'><script src='https://ad.example/ad.js'></script>"));assertEquals("https://cdn.example/a.m3u8",KissAnime.direct("sources:[{file:'https://cdn.example/a.m3u8'}]"));assertFalse(KissAnime.embed("https://megaplay.buzz.evil.test/"));}
 @Test public void captionsValidateDeduplicateAndSetLanguages() throws Exception {StreamProtocol.Stream s=new StreamProtocol.Stream("https://cdn.example/a.m3u8","");JSONObject data=new JSONObject("{\"tracks\":[{\"file\":\"https://cdn.example/en.srt\",\"label\":\"English\"},{\"file\":\"file:///x\"},{\"file\":\"https://cdn.example/no.vtt\",\"label\":\"Norwegian\"}]}");MediaCaptions.read(data,s);MediaCaptions.read(data,s);assertEquals(2,s.subtitles.size());assertEquals("en",s.subtitles.get(0).language);assertEquals("application/x-subrip",s.subtitles.get(0).mime);assertEquals("no",s.subtitles.get(1).language);}
 @Test public void stickDeadZoneAndRepeat(){DirectionRepeater r=new DirectionRepeater();assertEquals(0,r.update(.2f,.1f,0));assertEquals(2,r.update(.8f,0,10));assertEquals(0,r.update(.8f,0,200));assertEquals(2,r.update(.8f,0,330));assertEquals(0,r.update(.8f,0,400));assertEquals(3,r.update(0,-.8f,410));assertEquals(0,r.update(0,0,420));assertEquals(3,r.update(0,-.8f,421));}
 @Test public void mediaLinkIdentitySurvivesPersistence() throws Exception {CatalogItem a=new CatalogItem("local",0,0,0,"A","","","","content://one"),b=new CatalogItem("local",0,0,0,"B","","","","content://two");assertNotEquals(a.key(),b.key());assertEquals(a.key(),CatalogItem.saved(a.json()).key());assertEquals("content://one",CatalogItem.saved(a.json()).link);}
 @Test public void archiveFilesRejectPrivateAndEncodePaths() throws Exception {JSONObject root=new JSONObject("{\"files\":[{\"name\":\"movie one.mp4\",\"format\":\"MPEG4\"},{\"name\":\"private.mp4\",\"format\":\"MPEG4\",\"private\":\"true\"},{\"name\":\"readme.txt\",\"format\":\"Text\"}]}");CatalogPage p=ArchiveMedia.filesJson(root,"test-item",1);assertEquals(1,p.items.size());assertTrue(p.items.get(0).link.contains("movie%20one.mp4"));assertFalse(ArchiveMedia.identifier("../private"));}
 @Test public void tvScheduleBoundariesAndValidation(){assertTrue(TvChannels.valid(TvChannels.HOURS));assertEquals(0,TvChannels.at(TvChannels.HOURS,5));assertEquals(1,TvChannels.at(TvChannels.HOURS,6));assertEquals(9,TvChannels.at(TvChannels.HOURS,23));assertFalse(TvChannels.valid(new int[]{0,1,1,3,4,5,6,7,8,9}));}
 @Test public void mtvWeightsAndCustomFusion(){int[] weights=new int[16];weights[3]=100;assertEquals(3,MtvPolicy.pick(weights,-1));assertEquals("my custom videos",MtvPolicy.query(0,0,weights,4,"my custom videos"));assertTrue(MtvPolicy.query(12,2,weights,4,"").contains("Rock karaoke"));}
 @Test public void spotifyTracksMapToMusicQueries() throws Exception {JSONObject root=new JSONObject("{\"props\":{\"pageProps\":{\"state\":{\"data\":{\"entity\":{\"trackList\":[{\"title\":\"Song\",\"subtitle\":\"Artist\"}]}}}}}}");CatalogItem item=MusicEngine.spotifyJson(root).items.get(0);assertEquals("music-query",item.kind);assertEquals("Artist Song",item.link);}
 @Test public void rangeRequestsPreserveSignaturesAndAvoidCacheCollisions(){String url="https://cdn.googlevideo.com/videoplayback?sig=A%2FB%2BC&range=0-123&clen=999999&rn=1";String first=MediaRange.url(url,0,1024),later=MediaRange.url(url,1048576,1024);assertEquals("https://cdn.googlevideo.com/videoplayback?sig=A%2FB%2BC&clen=999999&range=0-1023",first);assertNotEquals(first,later);assertTrue(later.endsWith("range=1048576-1049599"));}
 @Test public void rangeRequestsHandleBareAddresses(){assertEquals("https://cdn.googlevideo.com/file?range=42-141",MediaRange.url("https://cdn.googlevideo.com/file#discard",42,100));}
 @Test public void phoneLayoutAdaptsToWindowAndOverride(){assertTrue(LibraryLayout.compact(0,360,780));assertTrue(LibraryLayout.compact(0,780,360));assertFalse(LibraryLayout.compact(0,1280,720));assertTrue(LibraryLayout.compact(1,1280,720));assertFalse(LibraryLayout.compact(2,360,780));}
 @Test public void phonePostersKeepReadableColumns(){assertEquals(2,LibraryLayout.columns(360,true));assertEquals(3,LibraryLayout.columns(480,true));assertEquals(8,LibraryLayout.columns(1280,true));assertEquals(6,LibraryLayout.columns(1280,false));}
}